import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # 1. Deduplicate events by seq (at-least-once delivery -> apply once)
    cdc_events = cdc_events.drop_duplicates(subset="seq", keep="first")

    # Build mutable state dict keyed by order_id
    target_dict = {}
    for row in target_state.itertuples(index=False):
        target_dict[int(row.order_id)] = {
            "status": row.status,
            "amount": row.amount,
            "last_seq": int(row.last_seq),
        }

    tombstones = []

    # Group events by order_id, process each order's events in seq order
    if not cdc_events.empty:
        for order_id, grp in cdc_events.groupby("order_id"):
            order_id = int(order_id)
            grp_sorted = grp.sort_values("seq", kind="mergesort")

            existing = target_dict.get(order_id)
            watermark = existing["last_seq"] if existing is not None else None

            if watermark is not None:
                grp_sorted = grp_sorted[grp_sorted["seq"] > watermark]

            if grp_sorted.empty:
                continue

            state = dict(existing) if existing is not None else None
            last_op = None
            last_seq = None

            for ev in grp_sorted.itertuples(index=False):
                op = ev.op
                seq = int(ev.seq)
                if op in ("I", "U"):
                    if state is not None:
                        amt = ev.amount
                        if op == "U" and pd.isna(amt):
                            amt = state["amount"]
                        state = {
                            "status": ev.status,
                            "amount": amt,
                            "last_seq": seq,
                        }
                    else:
                        state = {
                            "status": ev.status,
                            "amount": ev.amount,
                            "last_seq": seq,
                        }
                    last_op = op
                    last_seq = seq
                elif op == "D":
                    if state is not None:
                        state = None
                        last_op = "D"
                        last_seq = seq
                    # else: no-op, D for missing order does nothing
                # any other op value is not specified; ignore defensively

            if state is not None:
                target_dict[order_id] = state
            else:
                if order_id in target_dict:
                    del target_dict[order_id]

            if last_op == "D":
                tombstones.append((order_id, last_seq))

    # Build new_state output
    if target_dict:
        order_ids = sorted(target_dict.keys())
        new_state_rows = []
        for oid in order_ids:
            s = target_dict[oid]
            new_state_rows.append(
                {
                    "order_id": oid,
                    "status": s["status"],
                    "amount": s["amount"],
                    "last_seq": s["last_seq"],
                }
            )
        new_state = pd.DataFrame(
            new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
        )
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")
        new_state["amount"] = new_state["amount"].astype("float64")
        new_state["status"] = new_state["status"].astype(object)
    else:
        new_state = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "status": pd.Series(dtype=object),
                "amount": pd.Series(dtype="float64"),
                "last_seq": pd.Series(dtype="int64"),
            }
        )

    # Build tombstones output
    if tombstones:
        tombstones_sorted = sorted(tombstones, key=lambda x: x[0])
        tombstones_df = pd.DataFrame(
            tombstones_sorted, columns=["order_id", "deleted_seq"]
        )
        tombstones_df["order_id"] = tombstones_df["order_id"].astype("int64")
        tombstones_df["deleted_seq"] = tombstones_df["deleted_seq"].astype("int64")
    else:
        tombstones_df = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "deleted_seq": pd.Series(dtype="int64"),
            }
        )

    return {"new_state": new_state, "tombstones": tombstones_df}
